def transform(grid):
    # Recolor the isolated perpendicular bar sharing the same color as the
    # cross's long bar, using the color of the cross itself.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import deque, Counter
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if not v or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); pts=[]
            while q:
                x,y=q.popleft(); pts.append((x,y))
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and grid[a][b]==v and (a,b) not in seen:
                        seen.add((a,b)); q.append((a,b))
            comps.append((v,pts))
    # Find a long straight component (bar) crossed by a short perpendicular
    # arm of another color. The bar's color is copied to matching same-color
    # motifs; the crossed horizontal/vertical bar itself changes to cross color.
    for color,pts in comps:
        rr={r for r,c in pts}; cc={c for r,c in pts}
        if len(pts)<4 or (len(rr)>1 and len(cc)>1): continue
        # identify a separate-color component making a perpendicular crossing
        for other,op in comps:
            if other==color: continue
            for r,c in op:
                if (r in rr and c in cc) or (r in rr and len(cc)==1 and c in cc) or (c in cc and len(rr)==1 and r in rr):
                    # Not directly connected due color boundary; require near crossing position
                    if len(rr)==1 and c in cc or len(cc)==1 and r in rr:
                        for x,y in pts: out[x][y]=other
                        return out
    # ARC object rule: in this pattern the full-length bar (6) is unchanged;
    # only matching-color bar that intersects its perpendicular marker is recolored.
    return out

