    colors={v for row in grid for v in row if v!=bg}
    # Find long straight divider arms meeting at a corner; recolor non-background
    # objects enclosed on the inside of that L to the divider color.
    for color in colors:
        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        rows={r for r,c in pts}; cols={c for r,c in pts}
        if len(rows)<3 or len(cols)<3: continue
        # T-shaped cross/line layouts: select the largest horizontal and vertical runs.
        hruns=[]
        for r in rows:
            cs=[c for rr,c in pts if rr==r]
            if len(cs)>=3: hruns.append((r,min(cs),max(cs),len(cs)))
        vruns=[]
        for c in cols:
            rs=[r for r,cc in pts if cc==c]
            if len(rs)>=3: vruns.append((c,min(rs),max(rs),len(rs)))
        for r,c0,c1,hn in hruns:
